// Calcula las alertas de variación 24h a partir de la respuesta de GET /stats.
// Umbral: RATES_ALERT_PCT (por defecto 3). Un valor vacío, no numérico o <= 0 usa 3.
// Si la instancia bloquea $env (N8N_BLOCK_ENV_ACCESS_IN_NODE=true) se usan los valores por defecto.
const envVar = (name) => {
  try {
    return $env[name];
  } catch (e) {
    return undefined;
  }
};
const rawThreshold = Number.parseFloat(envVar('RATES_ALERT_PCT') ?? '');
const threshold = Number.isFinite(rawThreshold) && rawThreshold > 0 ? rawThreshold : 3;
const pageUrl = String(envVar('RATES_BASE_URL') ?? '').replace(/\/+$/, '') + '/';

// Deduplicación duradera: guarda source|latest_date ya avisados en los datos estáticos del flujo.
// n8n solo persiste estos datos en ejecuciones de producción (flujo activo), no en pruebas manuales.
const staticData = $getWorkflowStaticData('global');
const alerted = staticData.alerted && typeof staticData.alerted === 'object' ? staticData.alerted : {};
const KEEP_MS = 7 * 24 * 3600 * 1000;
const nowMs = Date.now();
for (const [key, at] of Object.entries(alerted)) {
  if (!(nowMs - Date.parse(at) < KEEP_MS)) delete alerted[key];
}

const isNum = (v) => typeof v === 'number' && Number.isFinite(v);
const invalid = [];
const duplicates = [];
const alerts = [];
const seenSources = new Set();
let checked = 0;

$input.all().forEach((item, index) => {
  const s = item.json;
  if (!s || typeof s !== 'object' || Object.keys(s).length === 0) return; // respuesta vacía: nada que revisar
  const w = s.change && typeof s.change === 'object' ? s.change['24h'] : undefined;
  if (typeof s.source !== 'string' || !s.source || !isNum(s.latest) || typeof s.latest_date !== 'string' || w === undefined) {
    invalid.push({ index, reason: 'entrada de /stats sin source, latest, latest_date o change' });
    return;
  }
  checked += 1;
  if (w === null) return; // sin historia de 24 h
  if (!isNum(w.pct) || !isNum(w.from_price) || typeof w.from_date !== 'string') {
    invalid.push({ index, source: s.source, reason: 'change.24h sin pct, from_price o from_date numéricos' });
    return;
  }
  if (Math.abs(w.pct) < threshold) return;
  const key = s.source + '|' + s.latest_date;
  if (seenSources.has(s.source) || alerted[key]) {
    duplicates.push(key);
    return;
  }
  seenSources.add(s.source);
  alerts.push({
    key,
    source: s.source,
    label: typeof s.label === 'string' && s.label ? s.label : s.source,
    unit: typeof s.unit === 'string' ? s.unit : '',
    price: s.latest,
    latest_date: s.latest_date,
    pct: w.pct,
    abs: isNum(w.abs) ? w.abs : s.latest - w.from_price,
    from_price: w.from_price,
    from_date: w.from_date,
  });
});

if (checked === 0 && invalid.length > 0) {
  throw new Error('Respuesta de /stats malformada: ' + invalid.length + ' entradas inválidas, ninguna válida');
}

for (const a of alerts) alerted[a.key] = new Date(nowMs).toISOString();
staticData.alerted = alerted;
staticData.statsDown = false;

const fmt = (n, d) => n.toLocaleString('es-VE', { minimumFractionDigits: d, maximumFractionDigits: d });
const lines = alerts.map((a) => {
  const sign = a.pct > 0 ? '+' : '';
  return '- ' + a.label + ': ' + fmt(a.price, 2) + ' ' + a.unit + ' (' + sign + fmt(a.pct, 2) + ' % en 24 h; antes ' +
    fmt(a.from_price, 2) + ' el ' + a.from_date + '; último dato ' + a.latest_date + ')';
});
const subject = '[ves-rates] Variación 24 h >= ' + threshold + ' %: ' + alerts.map((a) => a.source).join(', ');
const message = 'Variación fuerte en las tasas VES (umbral ' + threshold + ' %):\n' + lines.join('\n') + '\n\nVer: ' + pageUrl;

return [{ json: { threshold, checked, alerts, duplicates, invalid, subject, message } }];

// Avisa una sola vez por caída: el aviso se repite solo después de que /stats vuelva a responder bien.
const staticData = $getWorkflowStaticData('global');
if (staticData.statsDown === true) return [];
staticData.statsDown = true;
const err = $input.first().json.error;
const detail = typeof err === 'string' ? err : (err && err.message) || JSON.stringify(err ?? 'error desconocido');
return [{
  json: {
    subject: '[ves-rates] Alertas horarias sin datos',
    message: 'No se pudo leer o interpretar GET /stats: ' + detail +
      '\nEste aviso no se repite hasta que /stats vuelva a responder bien.',
  },
}];
